const { useState } = React;

function Result({ status }) {
  if (status === 'loading') return <p>불러오는 중...</p>;
  if (status === 'error') return <p className="error">상품을 불러오지 못했습니다.</p>;
  if (status === 'empty') return <p>검색 결과가 없습니다.</p>;
  return <ul><li>셔츠</li><li>모자</li></ul>;
}

function App() {
  const [status, setStatus] = useState('loading');
  return (
    <main>
      {['loading', 'error', 'empty', 'success'].map((value) => (
        <button key={value} type="button" onClick={() => setStatus(value)}>{value}</button>
      ))}
      <Result status={status} />
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

